package mezz.jei.library.plugins.vanilla.cooking.fuel;

import java.util.Comparator;
import java.util.List;
import mezz.jei.api.recipe.vanilla.IJeiFuelingRecipe;
import mezz.jei.api.runtime.IIngredientManager;
import mezz.jei.common.platform.IPlatformItemStackHelper;
import mezz.jei.common.platform.Services;
import mezz.jei.library.plugins.vanilla.cooking.fuel.FuelingRecipe;
import net.minecraft.world.item.ItemStack;

public final class FuelRecipeMaker {
    private FuelRecipeMaker() {
    }

    public static List<IJeiFuelingRecipe> getFuelRecipes(IIngredientManager ingredientManager) {
        IPlatformItemStackHelper itemStackHelper = Services.PLATFORM.getItemStackHelper();
        return ingredientManager.getAllItemStacks().stream().mapMulti((stack, consumer) -> {
            int burnTime = itemStackHelper.getBurnTime((ItemStack)stack);
            if (burnTime > 0) {
                consumer.accept(new FuelingRecipe(List.of(stack), burnTime));
            }
        }).sorted(Comparator.comparingInt(IJeiFuelingRecipe::getBurnTime)).toList();
    }
}

